17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.regex.Pattern;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
37	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
65	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        validateRequiredFields(ownerFieldsDto);
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
120	        rejectDuplicateTelephone(telephone);
121	        owner.setTelephone(telephone);
122	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
123	        if (owner.getRegistrationDate() == null) {
124	            owner.setRegistrationDate(LocalDate.now());
125	        }
126	        this.clinicService.saveOwner(owner);
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        headers.setLocation(UriComponentsBuilder.newInstance()
129	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
130	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
131	    }
132	
133	    /**
134	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
135	     * offending field so the client learns about all of them at once.
136	     *
137	     * @param ownerFieldsDto the submitted owner fields
138	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
139	     *                                     missing or blank
140	     */
141	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
142	        List<String> errors = new ArrayList<>();
143	        if (isBlank(ownerFieldsDto.getFirstName())) {
144	            errors.add("firstName");
145	        }
146	        if (isBlank(ownerFieldsDto.getLastName())) {
147	            errors.add("lastName");
148	        }
149	        if (isBlank(ownerFieldsDto.getAddress())) {
150	            errors.add("address");
151	        }
152	        if (isBlank(ownerFieldsDto.getCity())) {
153	            errors.add("city");
154	        }
155	        if (isBlank(ownerFieldsDto.getTelephone())) {
156	            errors.add("telephone");
157	        }
158	        if (!errors.isEmpty()) {
159	            throw new MissingOwnerFieldsException(errors);
160	        }
161	    }
162	
163	    private boolean isBlank(String value) {
164	        return value == null || value.isBlank();
165	    }
166	
167	    /**
168	     * Normalizes a submitted telephone by removing every non-digit character and requiring the
169	     * result to be exactly 10 digits.
170	     *
171	     * @param telephone the raw telephone value as submitted
172	     * @return the 10-digit normalized telephone
173	     * @throws InvalidTelephoneException if the stripped value is not exactly 10 digits
174	     */
175	    private String normalizeTelephone(String telephone) {
176	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
177	        if (digits.length() != 10) {
178	            throw new InvalidTelephoneException(telephone);
179	        }
180	        return digits;
181	    }
182	
183	    /**
184	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
185	     * value is treated as absent and returns {@code null}); when present the value must be a
186	     * syntactically valid address, and is stored and returned lower-cased.
187	     *
188	     * @param email the raw email value as submitted, may be {@code null}
189	     * @return the lower-cased email, or {@code null} when none was supplied
190	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
191	     */
192	    private String normalizeEmail(String email) {
193	        if (email == null || email.isBlank()) {
194	            return null;
195	        }
196	        String normalized = email.trim().toLowerCase();
197	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
198	            throw new InvalidEmailException(email);
199	        }
200	        return normalized;
201	    }
202	
203	    /**
204	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
205	     * unique across owners. Existing telephones are normalized the same way before comparison.
206	     *
207	     * @param normalizedTelephone the normalized telephone of the owner being created
208	     * @throws DuplicateTelephoneException if another owner already uses the same normalized telephone
209	     */
210	    private void rejectDuplicateTelephone(String normalizedTelephone) {
211	        boolean inUse = this.clinicService.findAllOwners().stream()
212	            .map(Owner::getTelephone)
213	            .filter(existing -> existing != null)
214	            .map(existing -> existing.replaceAll("\\D", ""))
215	            .anyMatch(normalizedTelephone::equals);
216	        if (inUse) {
217	            throw new DuplicateTelephoneException(normalizedTelephone);
218	        }
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
224	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
225	        if (currentOwner == null) {
226	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	        }
228	        currentOwner.setAddress(ownerFieldsDto.getAddress());
229	        currentOwner.setCity(ownerFieldsDto.getCity());
230	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
231	        currentOwner.setLastName(ownerFieldsDto.getLastName());
232	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
233	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
234	        this.clinicService.saveOwner(currentOwner);
235	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
236	    }
237	
238	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
239	    @Transactional
240	    @Override
241	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
242	        Owner owner = this.clinicService.findOwnerById(ownerId);
243	        if (owner == null) {
244	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
245	        }
246	        this.clinicService.deleteOwner(owner);
247	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
248	    }
249	
250	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
251	    @Override
252	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
253	        Owner owner = this.clinicService.findOwnerById(ownerId);
254	        if (owner == null) {
255	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
256	        }
257	        HttpHeaders headers = new HttpHeaders();
258	        Pet pet = petMapper.toPet(petFieldsDto);
259	        owner.setId(ownerId);
260	        pet.setOwner(owner);
261	        pet.getType().setName(null);
262	        this.clinicService.savePet(pet);
263	        PetDto petDto = petMapper.toPetDto(pet);
264	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
265	            .buildAndExpand(pet.getId()).toUri());
266	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
267	    }
268	
269	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
270	    @Override
271	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
272	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
273	        if (currentOwner != null) {
274	            Pet currentPet = this.clinicService.findPetById(petId);
275	            if (currentPet != null) {
276	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
277	                currentPet.setName(petFieldsDto.getName());
278	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
279	                this.clinicService.savePet(currentPet);
280	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
281	            }
282	        }
283	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
284	    }
285	
286	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
287	    @Override
288	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
289	        HttpHeaders headers = new HttpHeaders();
290	        Visit visit = visitMapper.toVisit(visitFieldsDto);
291	        Pet pet = new Pet();
292	        pet.setId(petId);
293	        visit.setPet(pet);
294	        this.clinicService.saveVisit(visit);
295	        VisitDto visitDto = visitMapper.toVisitDto(visit);
296	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
297	            .buildAndExpand(visit.getId()).toUri());
298	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
299	    }
300	
301	
302	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
303	    @Override
304	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
305	        Owner owner = this.clinicService.findOwnerById(ownerId);
306	        if (owner != null) {
307	            Pet pet = owner.getPet(petId);
308	            if (pet != null) {
309	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
310	            }
311	        }
312	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
313	    }
314	}
